class PictureData(APIModel):
    """The parameters of the new Picture. Give the image either as a file (path) or as its bytes (imageData), not both."""
    path: str | None = Field(
        None,
        description="The full path of a PNG, JPEG, GIF, TIFF or BMP image file. The image is copied into the project: the picture does not change when the file changes or is deleted later.",
    )
    imageData: str | None = Field(
        None,
        description="The PNG, JPEG, GIF, TIFF or BMP image file as base64 text, instead of path.",
    )
    name: str | None = Field(
        None,
        description="Optional name of the picture. By default the file name of path, or empty for imageData.",
    )
    position: Coordinate2D = Field(
        ...,
        description="Where the anchor point of the picture is placed, in model units (on a layout in layout units).",
    )
    anchorPoint: PictureAnchorPoint | None = Field(
        None,
        description="The point of the picture's box that is placed at position and that the picture is rotated around. BottomLeft by default.",
    )
    width: float | None = Field(
        None,
        description="The width of the picture in model units. When only height is given, the width keeps the proportions of the image.",
        gt=0.0,
    )
    height: float | None = Field(
        None,
        description="The height of the picture in model units. When only width is given, the height keeps the proportions of the image.",
        gt=0.0,
    )
    angle: float | None = Field(
        None,
        description="The rotation angle of the picture in radians, around its anchor point. 0 by default.",
    )
    mirrored: bool | None = Field(
        None,
        description="Mirror the picture to its local vertical axis. false by default.",
    )
    transparent: bool | None = Field(
        None,
        description="Draw the white pixels of the picture transparent. false by default.",
    )
    floorInd: float | None = Field(
        None,
        description="The identifier of the floor. Optional parameter, by default the current floor is used.",
    )
    layerIndex: int | None = Field(
        None,
        description="Layer attribute index to place the picture on. Optional parameter, by default the layer of the Picture tool defaults is used.",
        ge=1,
    )


class PictureDetails(APIModel):
    """The settings of a Picture element (an image placed with the Picture tool on a floor plan, worksheet, detail or layout)."""
    name: str = Field(
        ...,
        description="The name of the picture (API_PictureType::pictName), usually the name of the image file it was placed from.",
    )
    mimeType: str = Field(
        ...,
        description="The MIME type of the image, e.g. image/png or image/jpeg. Empty when Archicad does not report it.",
    )
    box: BoundingBox2D = Field(
        ...,
        description="The box the picture is drawn in, in model units, before its rotation by angle. For an unmirrored picture this is API_PictureType::destBox; a mirrored picture is drawn one width away from its stored destBox (along the rotated x axis), and this box is the drawn one, so a mirrored and an unmirrored picture drawn at the same place report the same box.",
    )
    position: Coordinate2D | None = Field(
        None,
        description="Where the anchor point of the picture is, the point it is rotated around, in model units (on a layout in layout units): the anchorPoint of its box, worked out the way ModifyPictures places it, so ModifyPictures takes it back with the same key and the picture stays where it is. For an unmirrored picture it is the anchorPoint of box; for a mirrored one it follows ModifyPictures, which shifts the stored box by one width along x without the rotation.",
    )
    width: float = Field(..., description="The width of the picture in model units: box.xMax - box.xMin.")
    height: float = Field(
        ...,
        description="The height of the picture in model units: box.yMax - box.yMin.",
    )
    pixelWidth: int = Field(..., description="The width of the image in pixels.")
    pixelHeight: int = Field(..., description="The height of the image in pixels.")
    angle: float = Field(..., description="The rotation angle of the picture in radians.")
    mirrored: bool = Field(..., description="Whether the picture is mirrored to its local vertical axis.")
    transparent: bool = Field(
        ...,
        description="Whether the white pixels of the picture are drawn transparent.",
    )
    anchorPoint: PictureAnchorPoint


