    LEFT_TOP = "LeftTop"
    MIDDLE_TOP = "MiddleTop"
    RIGHT_TOP = "RightTop"
    LEFT_MIDDLE = "LeftMiddle"
    MIDDLE_MIDDLE = "MiddleMiddle"
    RIGHT_MIDDLE = "RightMiddle"
    LEFT_BOTTOM = "LeftBottom"
    MIDDLE_BOTTOM = "MiddleBottom"
