    bold: bool = Field(..., description="Bold dimension text.")
    italic: bool = Field(..., description="Italic dimension text.")
    underline: bool = Field(..., description="Underlined dimension text.")
    hideWithBaseElem: bool | None = Field(
        None,
        description="Hide the dimension together with its associated element. Read from Archicad 29; absent on earlier versions.",
    )
    textContent: LevelDimensionTextContent = Field(
        ...,
        description="Content of the dimension text: 'Measured' (the level value) or 'Custom' (customText).",
    )
    customText: str | None = Field(
        None,
        description="The custom content of the dimension text, with its Autotext keys as keys (read with the autotext flag off), in the form CreateLevelDimensions and ModifyLevelDimensions take. Present when textContent is 'Custom'.",
    )
    secondTextContent: LevelDimensionTextContent = Field(
        ...,
        description="Content of the second text, shown by the marker types with two texts: 'Measured' or 'Custom' (secondCustomText).",
    )
    secondCustomText: str | None = Field(
        None,
        description="The custom content of the second text, as customText. Present when secondTextContent is 'Custom'.",
    )


