class ShellData(APIModel):
    """The parameters of the new Shell."""
    favoriteName: str | None = Field(
        None,
        description="Optional name of a Shell favorite to base the new element on. Its settings are applied first, then the explicitly given fields override them.",
    )
    id: str | None = Field(
        None,
        description="Optional Element ID of the new element. When omitted the element gets the next automatic ID of its tool.",
    )
    shellClass: ShellClass = Field(
        ...,
        description="Extruded: 'profile' swept along 'extrusionVector'. Revolved: 'profile' turned around 'axis'. Ruled: a surface ruled between 'profile' and 'secondProfile'.",
    )
    floorIndex: int | None = Field(
        None,
        description="Optional story index of the shell. Without it the shell is placed on the story of the Shell tool defaults.",
    )
    basePlane: CoordinateSystem3D | None = Field(
        None,
        description="Base plane of the shell, in project coordinates; the profiles, the extrusion, the axis and the contour and hole polygons are given in it. The project axes by default, except for a Revolved shell, whose default base plane stands upright (its Y axis is the project Z axis), so the profile's x is the radius and its y the height.",
    )
    profile: ShellProfile = Field(
        ...,
        description="The profile polyline. Extruded: in the plane across the extrusion, x horizontal and y up. Revolved: in the base plane's XY plane. Ruled: in the XY plane of 'profilePlane'.",
    )
    thickness: float | None = Field(
        None,
        description="Only takes effect on a Basic shell; a Composite shell takes its thickness from the composite.",
        gt=0.0,
    )
    isFlipped: bool | None = Field(
        None,
        description="Applies the thickness to the other side of the reference surface.",
    )
    structureType: RoofStructureType | None = None
    buildingMaterialId: AttributeId | None = None
    compositeId: AttributeId | None = None
    extrusionVector: Coordinate3D | None = Field(
        None,
        description="Extruded only, required: the direction and length of the extrusion, in base plane coordinates.",
    )
    extrusionStart: Coordinate3D | None = Field(
        None,
        description="Extruded only: the point the extrusion starts from, in base plane coordinates.",
    )
    shapePlaneTilt: float | None = Field(None, description="Extruded only: tilt of the profile's plane, in radians.")
    begPlaneTilt: float | None = Field(
        None,
        description="Extruded only: tilt of the start plane of the extrusion, in radians.",
    )
    endPlaneTilt: float | None = Field(
        None,
        description="Extruded only: tilt of the end plane of the extrusion, in radians.",
    )
    slantAngle: float | None = Field(
        None,
        description="Extruded and Revolved: slant of the extrusion vector or of the profile, in radians.",
    )
    axis: CoordinateSystem3D | None = Field(
        None,
        description="Revolved only: the coordinate system whose Z axis the profile is turned around, in base plane coordinates. By default the base plane's Y axis.",
    )
    revolutionAngle: float | None = Field(
        None,
        description="Revolved only: the angle the profile is turned through, in radians. 2*pi (a full turn) by default.",
    )
    beginAngle: float | None = Field(
        None,
        description="Revolved only: the angle the revolution starts at, in radians.",
    )
    distortionAngle: float | None = Field(
        None,
        description="Revolved only: shear of the revolution, in radians. pi/2 (no shear) by default.",
    )
    segmentsByCircle: int | None = Field(
        None,
        description="Revolved only: the number of segments a full circle is resolved into.",
        ge=3,
    )
    secondProfile: ShellProfile | None = Field(
        None,
        description="Ruled only, required: the second profile polyline, in the XY plane of 'secondProfilePlane'.",
    )
    profilePlane: CoordinateSystem3D | None = Field(
        None,
        description="Ruled only, required: the plane of 'profile', in base plane coordinates.",
    )
    secondProfilePlane: CoordinateSystem3D | None = Field(
        None,
        description="Ruled only, required: the plane of 'secondProfile', in base plane coordinates.",
    )
    morphingRule: MorphingRule | None = None
    contour: ShellCutPolygon | None = Field(
        None,
        description="Optional clipping contour: only the part of the shell inside this polygon, seen along the Z axis of its plane, is kept. Its 'depth' is ignored.",
    )
    holes: list[ShellCutPolygon] | None = Field(
        None,
        description="Optional holes, each requiring 'depth' to extrude its cutting polygon along the Z axis of its plane.",
    )
    begShapeEdgeTrim: ShellEdgeTrim | None = Field(
        None,
        description="Optional trim of the profile's edges at the start of the shell (the start plane of an extrusion, the begin angle of a revolution, the first profile of a ruled shell). Perpendicular at pi/2 by default, as the Shell tool draws it, also when favoriteName is given.",
    )
    endShapeEdgeTrim: ShellEdgeTrim | None = Field(
        None,
        description="Optional trim of the profile's edges at the end of the shell. Perpendicular at pi/2 by default.",
    )
    begSideEdgeTrim: ShellEdgeTrim | None = Field(
        None,
        description="Optional trim of the edge that the profile's first point sweeps from the start to the end of the shell. Perpendicular at pi/2 by default.",
    )
    endSideEdgeTrim: ShellEdgeTrim | None = Field(
        None,
        description="Optional trim of the edge that the profile's last point sweeps. Perpendicular at pi/2 by default.",
    )


class ShellEdgeMaterials(APIModel):
    """The custom surface of the edges of a shell (API_ContourEdgeData::sideMaterial of the shell class's edge data). An overridden edge shows its own surface; one that is not overridden shows the shell's side surface (sideMaterial)."""
    begShapeEdge: OverriddenMaterial | None = Field(
        None,
        description="The edges of the profile at the begin of the shell: the start of the extrusion or revolution, or the first profile of a ruled shell (begShapeEdgeData).",
    )
    endShapeEdge: OverriddenMaterial | None = Field(
        None,
        description="The edges of the profile at the end of the shell: the end of the extrusion or revolution, or the second profile of a ruled shell (endShapeEdgeData).",
    )
    begSideEdge: OverriddenMaterial | None = Field(
        None,
        description="The edge along the shell's surface from the first point of the profile (extrudedEdgeDatas, revolvedEdgeDatas or ruledEdgeDatas [0]).",
    )
    endSideEdge: OverriddenMaterial | None = Field(
        None,
        description="The edge along the shell's surface from the last point of the profile (extrudedEdgeDatas, revolvedEdgeDatas or ruledEdgeDatas [1]).",
    )


class ShellWithDetails(APIModel):
    elementId: ElementId
    structureType: ShellStructureType | None = None
    buildingMaterialId: AttributeId | None = None
    compositeId: AttributeId | None = None
    thickness: float | None = Field(
        None,
        description="The new thickness of a Basic shell, in meters (or of a shell this item makes Basic with 'structureType'). The shell's reference surface (the surface its profile and base plane define) stays in place and the thickness is measured from it to the side 'isFlipped' selects, so only the opposite face moves. A Composite shell takes its thickness from its composite: the item fails, and nothing of it is written; change the skins of the composite attribute, or make the shell Basic in the same item.",
        gt=0.0,
    )
    isFlipped: bool | None = Field(
        None,
        description="The side of the reference surface the thickness is applied to, as CreateShells takes it and GetDetailsOfElements returns it. Changing it keeps the reference surface in place and moves the body to its other side.",
    )
    contour: ShellCutPolygon | None = Field(
        None,
        description="Replaces the clipping contour (or adds one): only the part of the shell inside this polygon, seen along the Z axis of its plane, is kept. Its 'depth' is ignored. The polygon and its plane are in the coordinates of the shell's base plane, as GetDetailsOfElements returns them. The holes and the profile are kept.",
    )
    removeContour: bool | None = Field(
        None,
        description="True removes the clipping contour, so the whole shell is shown again. Not together with 'contour'.",
    )
    holes: list[ShellCutPolygon] | None = Field(
        None,
        description="Replaces all holes of the shell, each requiring 'depth' to extrude its cutting polygon along the Z axis of its plane; an empty array removes every hole. To change one hole, send all holes as GetDetailsOfElements returns them with that one changed. The contour and the profile are kept.",
    )
    topMaterial: OverriddenMaterial | None = Field(
        None,
        description="Overrides the surface of one face of the shell (topMaterial of GetDetailsOfElements); overridden false clears the override.",
    )
    sideMaterial: OverriddenMaterial | None = Field(
        None,
        description="Overrides the surface of the edges of the shell; overridden false clears the override.",
    )
    bottomMaterial: OverriddenMaterial | None = Field(
        None,
        description="Overrides the surface of the other face of the shell (bottomMaterial of GetDetailsOfElements); overridden false clears the override.",
    )
    materialsChained: bool | None = Field(
        None,
        description="Whether the surface materials are chained, as GetDetailsOfElements reports it.",
    )
    edgeMaterials: ShellEdgeMaterials | None = Field(
        None,
        description="The custom surface of individual edges of the shell, as GetDetailsOfElements reports them. Only the edges given are written; overridden false clears an edge's custom surface.",
    )
    extrusionVector: Coordinate3D | None = Field(
        None,
        description="Extruded shells only: the new direction and length of the extrusion, in base plane coordinates (as GetDetailsOfElements returns it). The profile, the base plane and the extrusion start are kept, so only the end of the shell moves. Cannot be given together with extrusionLength.",
    )
    extrusionLength: float | None = Field(
        None,
        description="Extruded shells only: the new length of the extrusion. The extrusion vector keeps its direction and is scaled to this length; the profile, the base plane and the extrusion start are kept, so only the end of the shell moves. Cannot be given together with extrusionVector.",
        gt=0.0,
    )
    profile: ShellProfile | None = Field(
        None,
        description="The new profile polyline, in the format and coordinates CreateShells takes and GetDetailsOfElements returns. Extruded: in the plane across the extrusion (x horizontal, y up). Revolved: in the base plane's XY plane. Ruled: the first profile, in the XY plane of profilePlane. It replaces the first profile polyline; the GUID, the base plane, the extrusion, the axis, the profile planes, the thickness and the cut contours are kept.",
    )
    secondProfile: ShellProfile | None = Field(
        None,
        description="Ruled shells only: the new second profile polyline, in the XY plane of secondProfilePlane, as CreateShells takes it and GetDetailsOfElements returns it. The first profile and both planes are kept unless given too.",
    )
    profilePlane: CoordinateSystem3D | None = Field(
        None,
        description="Ruled shells only: the new plane of the first profile, in base plane coordinates, as GetDetailsOfElements returns it. Only the parts given change: 'origin' alone moves the plane, the three axes (all together) turn it. The profile keeps its coordinates in the plane.",
    )
    secondProfilePlane: CoordinateSystem3D | None = Field(
        None,
        description="Ruled shells only: the new plane of the second profile, in base plane coordinates, as GetDetailsOfElements returns it. Only the parts given change, as for profilePlane.",
    )
    morphingRule: MorphingRule | None = Field(
        None,
        description="Ruled shells only: how the two profiles are joined, segment by segment (Paired) or smoothly.",
    )
    axis: CoordinateSystem3D | None = Field(
        None,
        description="Revolved shells only: the new coordinate system whose Z axis the profile is turned around, in base plane coordinates, as GetDetailsOfElements returns it. Only the parts given change: 'origin' alone moves the axis, the three axes (all together) turn it. The profile is kept.",
    )
    revolutionAngle: float | None = Field(
        None,
        description="Revolved shells only: the new angle the profile is turned through, in radians, at most 2*pi (a full turn).",
        gt=0.0,
        le=6.283185307179587,
    )
    beginAngle: float | None = Field(
        None,
        description="Revolved shells only: the new angle the revolution starts at, in radians.",
    )
    slantAngle: float | None = Field(
        None,
        description="Revolved shells only: the new slant of the profile, in radians.",
    )
    distortionAngle: float | None = Field(
        None,
        description="Revolved shells only: the new shear of the revolution, in radians, between 0 and pi; pi/2 is no shear.",
        gt=0.0,
        lt=3.141592653589793,
    )
    segmentType: ShellSegmentType | None = Field(
        None,
        description="Revolved shells only: how the curve is resolved into segments, by the segments of a full circle (segmentsByCircle) or of the revolution arc (segmentsByArc).",
    )
    segmentsByCircle: int | None = Field(
        None,
        description="Revolved shells only: the number of segments a full circle is resolved into, used when segmentType is ByCircle.",
        ge=3,
    )
    segmentsByArc: int | None = Field(
        None,
        description="Revolved shells only: the number of segments the revolution arc is resolved into, used when segmentType is ByArc.",
        ge=1,
    )
    segmentedSurfaces: bool | None = Field(
        None,
        description="Revolved shells only: whether the revolved surface is broken into planes along the revolution arc.",
    )
    cutBodyType: ShellCutBodyTypeUpdate | None = None
    displayOption: DisplayOption | None = Field(None, description="Floor Plan Display of the element.")
    viewDepthLimitation: ViewDepthLimitation | None = Field(
        None,
        description="Show Projection: how far the element is shown on the floor plan.",
    )
    isAutoOnStoryVisibility: bool | None = Field(
        None,
        description="When true, Archicad recomputes 'visibility' and 'fillVisibility' from the element's vertical extent and ignores values set for them. Setting 'visibility' or 'fillVisibility' without this field turns it off.",
    )
    visibility: StoryVisibility | None = Field(
        None,
        description="The stories the element's contour is shown on. Only the given fields change.",
    )
    fillVisibility: StoryVisibility | None = Field(
        None,
        description="The stories the element's cover fill is shown on. Only the given fields change.",
    )
    cutFillPen: OverriddenPen | None = Field(None, description="Overrides the pen of the cut fill.")
    cutFillBackgroundPen: OverriddenPen | None = Field(
        None, description="Overrides the background pen of the cut fill."
    )
    sectionContourPen: int | None = Field(None, description="Pen of the element's contour where it is cut.")
    sectionContourLineTypeId: AttributeId | None = Field(
        None, description="Line type of the element's contour where it is cut."
    )
    contourPen: int | None = Field(None, description="Pen of the element's uncut contour.")
    contourLineTypeId: AttributeId | None = Field(None, description="Line type of the element's uncut contour.")
    aboveViewLinePen: int | None = Field(
        None,
        description='Pen used when "Overhead All" is selected from the "Floor Plan Display" popup.',
    )
    aboveViewLineTypeId: AttributeId | None = Field(
        None,
        description='Line type used when "Overhead All" is selected from the "Floor Plan Display" popup.',
    )
    floorFill: ShellBaseFloorFill | None = Field(
        None,
        description="The cover fill of the element in the floor plan. Only the given fields change; read the orientation back with GetDetailsOfElements, Archicad may not apply all of it.",
    )


class SkylightData(APIModel):
    """The parameters of the new Skylight. The settings not given are the Skylight tool defaults' or the favorite's."""
    favoriteName: str | None = Field(
        None,
        description="Optional name of a Skylight favorite to base the new element on.",
    )
    id: str | None = Field(
        None,
        description="Optional Element ID of the new element. When omitted the element gets the next automatic ID of its tool.",
    )
    ownerId: ElementId = Field(
        ...,
        description="The roof (single- or multi-plane) or shell the skylight is placed in.",
    )
    libraryPartName: str | None = Field(
        None,
        description="Optional localized name of a skylight library part to place instead of the tool default's.",
    )
    anchorPosition: Coordinate2D = Field(
        ...,
        description="Global XY coordinates of the skylight's anchor point (API_SkylightType::anchorPosition). Archicad places the skylight on its owner roof or shell at this point; moving it onto another plane of a multi-plane roof has not been verified.",
    )
    anchorPoint: SkylightAnchorPoint | None = None
    fixMode: SkylightFixMode | None = None
    width: float | None = Field(None, gt=0.0)
    height: float | None = Field(None, gt=0.0)
    azimuthAngle: float | None = Field(
        None,
        description="Rotation angle of the skylight in the horizontal plane, measured clockwise, in radians (API_SkylightType::azimuthAngle).",
    )
    elevationAngle: float | None = Field(
        None,
        description="Elevation angle of the owner's surface at the skylight, in radians (API_SkylightType::elevationAngle). Archicad may set it again from the owner roof or shell.",
    )
    reflected: bool | None = Field(None, description="Mirror the skylight (API_OpeningBaseType::reflected).")
    displayOption: DisplayOption | None = None
    pen: int | None = Field(
        None,
        description="Pen of the skylight's floor plan symbol; used unless useObjectPens is true.",
        ge=0,
        le=255,
    )
    lineTypeId: AttributeId | None = Field(
        None,
        description="Line type of the skylight's floor plan symbol; used unless useObjectLineTypes is true.",
    )
