class ArcData(APIModel):
    """The parameters of the new Arc."""
    favoriteName: str | None = Field(
        None,
        description="Optional name of a favorite to base the new element on. Its settings are applied first, then the explicitly given fields override them.",
    )
    id: str | None = Field(
        None,
        description="Optional Element ID of the new arc. Arcs have no Element ID in Archicad 29: Archicad refuses it with error -2130313103 (APIERR_BADELEMENTTYPE, element has no info string), and the item then answers with that error and creates no arc. Leave it out unless your Archicad version keeps it (GetDetailsOfElements returns it as id).",
    )
    floorInd: float | None = Field(
        None,
        description="The identifier of the floor. Optional parameter, by default the current floor is used.",
    )
    layerIndex: int | None = Field(
        None,
        description="Layer attribute index to place the arc on. Optional parameter, by default the current layer is used.",
    )
    origin: Coordinate2D
    radius: float
    begAngle: float = Field(..., description="Beginning angle of the arc in radians.")
    endAngle: float = Field(..., description="End angle of the arc in radians.")
    angle: float | None = Field(
        None,
        description="Optional angle of the ellipse's 'a' axis in radians. Defaults to 0.0.",
    )
    ratio: float | None = Field(
        None,
        description="Optional 'a/b' ratio of the ellipse, as GetDetailsOfElements returns it. Defaults to 1.0, a circular arc.",
        gt=0.0,
    )
    reflected: bool | None = Field(
        None,
        description="Optional: is the ellipse reflected onto its smaller axis? By default the tool's (or the favorite's) setting is kept.",
    )
    startArrow: LineArrowhead | None = Field(
        None,
        description="Optional arrowhead at the start. Given, it is shown unless its visible is false; by default the tool's (or the favorite's) arrowhead is kept.",
    )
    endArrow: LineArrowhead | None = Field(
        None,
        description="Optional arrowhead at the end. Given, it is shown unless its visible is false; by default the tool's (or the favorite's) arrowhead is kept.",
    )
    linkedArrowAttributes: bool | None = Field(
        None,
        description="Optional: link (true) or unlink (false) the size and pen of the two arrowheads. By default the tool's (or the favorite's) setting is kept, and ends given a different size or pen are unlinked.",
    )
    roomSeparator: bool | None = Field(None, description="Is this a zone boundary line? Optional, defaults to false.")
    linePenIndex: int | None = Field(None, description="Optional pen index. By default the current pen is used.")
    lineTypeId: AttributeId | None = Field(
        None,
        description="Optional line type attribute. By default the current line type is used.",
    )


class ArcDetails(APIModel):
    """Geometry of an Arc or Circle element. begAngle/endAngle and startArrow/endArrow are only present for Arc (a Circle spans the full 0-2*PI range implicitly and has no ends)."""
    origin: Coordinate2D
    radius: float
    angle: float = Field(..., description="0.0, or the angle of the 'a' axis in radians.")
    ratio: float = Field(..., description="1.0, or 'a/b' of the ellipse.")
    begAngle: float | None = Field(
        None,
        description="Beginning angle of the arc in radians. Only present for Arc, not Circle.",
    )
    endAngle: float | None = Field(
        None,
        description="End angle of the arc in radians. Only present for Arc, not Circle.",
    )
    reflected: bool
    roomSeparator: bool | None = Field(None, description="Is this a zone boundary line?")
    linePenIndex: int | None = None
    lineTypeId: AttributeId | None = None
    startArrow: LineArrowhead | None = Field(
        None,
        description="The arrowhead at the start. Only present for Arc, not Circle.",
    )
    endArrow: LineArrowhead | None = Field(
        None, description="The arrowhead at the end. Only present for Arc, not Circle."
    )
    linkedArrowAttributes: bool | None = Field(
        None,
        description="Are the size and pen of the two arrowheads linked? Only present for Arc, not Circle, from Archicad 29.",
    )
    zCoordinate: float


class ArcSettings(APIModel):
    """Settings for modifying an Arc or Circle. begAngle/endAngle are only applied to Arc, ignored for Circle. startArrow/endArrow are only for Arc: a Circle has no ends and refuses them."""
    origin: Coordinate2D | None = None
    radius: float | None = None
    angle: float | None = None
    ratio: float | None = None
    begAngle: float | None = None
    endAngle: float | None = None
    reflected: bool | None = None
    roomSeparator: bool | None = None
    linePenIndex: int | None = None
    lineTypeId: AttributeId | None = None
    startArrow: LineArrowhead | None = Field(
        None,
        description="Optional arrowhead at the start of an Arc. Given, it is shown unless its visible is false; only the keys given are changed.",
    )
    endArrow: LineArrowhead | None = Field(
        None,
        description="Optional arrowhead at the end of an Arc. Given, it is shown unless its visible is false; only the keys given are changed.",
    )
    linkedArrowAttributes: bool | None = Field(
        None,
        description="Optional: link (true) or unlink (false) the size and pen of the two arrowheads of an Arc. A Circle refuses it.",
    )


class AssociativeDimensionOnSectionData(APIModel):
    favoriteName: str | None = Field(
        None,
        description="Optional name of a Dimension favorite to base the new dimension on, e.g. for its layer, line pen and markers. Its settings are applied first, then the command sets the geometry and its usual text placement. The favorite's text size, text pen and text frame are not applied (tested in Archicad 28): use textHeight, textPen and textFrame for the texts. The Dimension tool defaults are left as they were.",
    )
    layerIndex: int | None = Field(
        None,
        description="Optional layer attribute index to place the new dimension on. It must be an existing, unlocked layer. When omitted the dimension gets the layer of the favorite or of the Dimension tool defaults.",
        ge=1,
    )
    textHeight: float | None = Field(
        None,
        description="Optional height of the dimension texts in millimeters (paper size), applied to every witness point (on creation after favoriteName).",
        gt=0.0,
    )
    textPen: int | None = Field(
        None,
        description="Optional pen index of the dimension texts, applied to every witness point (on creation after favoriteName).",
        ge=1,
        le=255,
    )
    textFrame: bool | None = Field(
        None,
        description="Optional frame around the dimension texts (true: framed, false: not framed), applied to every witness point. Without it a new dimension gets the Dimension tool's setting.",
    )
    textStyle: DimensionTextStyle | None = Field(
        None,
        description="Optional font and style of the dimension texts (font, bold, italic, underline, width factor, spacing factor), applied to every witness point (on creation after favoriteName). Only the fields given are changed.",
    )
    appearance: DimensionAppearance | None = Field(
        None,
        description="Optional dimension type, as in the Dimension Settings. A new dimension is Linear without it, whatever favoriteName or the Dimension tool defaults say. Elevation gives level marks, e.g. on a vertical chain in a section.",
    )
    elevationOrigin: DimensionOrigin | None = Field(
        None,
        description="Optional level an Elevation dimension measures from. A new dimension gets the one of favoriteName or the Dimension tool defaults without it.",
    )
    elevationMarker: DimensionElevationMarker | None = Field(
        None,
        description="Optional marker of an Elevation dimension (Elevation dimension in the Dimension Settings); give any of its form, arrowAngle, arrowFilled, arrowUp and plusSign. The others stay as they are (on creation: as favoriteName or the Dimension tool defaults give them).",
    )
    linePen: int | None = Field(
        None,
        description="Optional pen of the dimension and witness lines.",
        ge=1,
        le=255,
    )
    marker: DimensionMarker | None = Field(
        None,
        description="Optional marker at the witness points; give any of its type, pen and size. The others stay as they are (on creation: as favoriteName or the Dimension tool defaults give them).",
    )
    textPlacement: DimensionTextPlacement | None = Field(
        None,
        description="Optional text placement method of the dimension texts, as in the Dimension Settings; give any of its fields. The others stay as they are (on creation: as favoriteName or the Dimension tool defaults give them).",
    )
    defaultWitnessForm: DefaultWitnessForm | None = Field(
        None,
        description="Optional witness line form, as in the Dimension Settings, applied to every witness point.",
    )
    defaultWitnessVal: float | None = Field(
        None,
        description="Optional value that goes with the witness line form, in meters (for Fix the length of the witness lines), applied to every witness point.",
        ge=0.0,
    )
    staticDimension: bool | None = Field(
        None,
        description="Optional Static dimension checkbox of the Dimension Settings (API defStaticDim). A new dimension is not static without it, whatever favoriteName or the Dimension tool defaults say. The witness points are written as given either way (by elementId or by coordinate).",
    )
    onlyDimensionText: bool | None = Field(
        None,
        description="Optional: show only the dimension texts, without the dimension and witness lines (API onlyDimensionText). Without it a new dimension gets the setting of favoriteName or of the Dimension tool defaults.",
    )
    openingHeightsInChain: bool | None = Field(
        None,
        description="Optional opening heights in the dimension chain, from the Dimension Details panel of the Dimension Settings (API detailedHoleDim): the heights of the doors and windows dimensioned are shown with the chain. Without it a new dimension gets the setting of favoriteName or of the Dimension tool defaults.",
    )
    openingHeightsNominal: bool | None = Field(
        None,
        description="Optional: the opening heights are the nominal heights, without the oversize (API nominalHoleDim; false: with the oversize). Without it a new dimension gets the setting of favoriteName or of the Dimension tool defaults.",
    )
    layeredElementDimensions: LayeredElementDimensions | None = Field(
        None,
        description="Optional automatic dimensioning of layered (composite) elements. Give any of the three; the others stay as they are. Without it a new dimension gets the setting of favoriteName or of the Dimension tool defaults.",
    )
    sectionElementId: ElementId | None = Field(
        None,
        description="The identifier of a single section element. Only one of sectionElementId and sectionElementIds can be given.",
    )
    sectionElementIds: list[ElementId] | None = Field(
        None,
        description="A list of section elements whose preset points are merged into one continuous dimension chain. Only one of sectionElementId and sectionElementIds can be given.",
        min_length=1,
    )
    referencePoint: Coordinate2D
    preset: Preset = Field(
        ...,
        description="OpeningEdges puts fixed points, not associated ones, at the edges of an Opening tool element as the section draws it: left and right for a horizontal direction, bottom and top for a vertical one. Archicad does not associate dimensions with openings in sections.",
    )
    direction: Coordinate2D | None = None
    skinBorderIndices: list[int] | None = Field(None, min_length=1)
